   241	func firstValue(c *gin.Context, keys ...string) string {
   242		if pathValue := c.Param(keys[0]); pathValue != "" {
   243			return pathValue
   244		}
   245		for _, key := range keys {
   246			if value := c.Query(key); value != "" {
   247				return value
   248			}
   249		}
   250		return ""
   251	}
