   253	func parsePositiveVersion(value string) (int64, bool) {
   254		if value == "" {
   255			return 0, false
   256		}
   257		for _, char := range value {
   258			if char < '0' || char > '9' {
   259				return 0, false
   260			}
   261		}
   262		number, err := strconv.ParseInt(value, 10, 64)
   263		if err != nil || number <= 0 {
   264			return 0, false
   265		}
   266		return number, true
   267	}
