   299	func buildConfigChanges(base, target, current *store.Version) []configChange {
   300		names := unionItemNames(base, target)
   301		changes := make([]configChange, 0, len(names))
   302		for _, name := range names {
   303			oldValue, oldExists := base.Item(name)
   304			newValue, newExists := target.Item(name)
   305	
   306			change := configChange{Name: name}
   307			switch {
   308			case !oldExists && newExists:
   309				value := newValue
   310				change.Type = "added"
   311				change.NewValue = &value
   312			case oldExists && !newExists:
   313				value := oldValue
   314				change.Type = "removed"
   315				change.OldValue = &value
   316			case oldExists && newExists && !bytes.Equal(oldValue, newValue):
   317				oldCopy, newCopy := oldValue, newValue
   318				change.Type = "modified"
   319				change.OldValue = &oldCopy
   320				change.NewValue = &newCopy
   321			default:
   322				continue
   323			}
   324			change.AffectsCurrent = changeIsCurrent(change, current)
   325			changes = append(changes, change)
   326		}
   327		return changes
   328	}
   329	
   330	func unionItemNames(base, target *store.Version) []string {
   331		seen := make(map[string]struct{})
   332		for _, name := range base.ItemNames() {
   333			seen[name] = struct{}{}
   334		}
   335		for _, name := range target.ItemNames() {
   336			seen[name] = struct{}{}
   337		}
   338		names := make([]string, 0, len(seen))
   339		for name := range seen {
   340			names = append(names, name)
   341		}
   342		sort.Strings(names)
   343		return names
   344	}
   345	
   346	func changeIsCurrent(change configChange, current *store.Version) bool {
   347		if current == nil {
   348			return false
   349		}
   350		currentValue, currentExists := current.Item(change.Name)
   351		switch change.Type {
   352		case "added", "modified":
   353			return currentExists && bytes.Equal(currentValue, *change.NewValue)
   354		case "removed":
   355			return !currentExists
   356		default:
   357			return false
   358		}
   359	}

