132	// PublishVersion persists a version and its configuration items without changing active state.
133	func (s *Store) PublishVersion(input VersionInput) error {
134		tx, err := s.db.Begin()
135		if err != nil {
136			return fmt.Errorf("begin publish: %w", err)
137		}
138		defer tx.Rollback()
139	
140		if input.Namespace == "" {
141			input.Namespace = input.NamespaceName
142		}
143		if input.Environment == "" {
144			input.Environment = input.Env
145		}
146		if input.Version == 0 {
147			input.Version = input.VersionNumber
148		}
149		if input.GrayLabel == nil {
150			input.GrayLabel = input.CanaryLabel
151		}
152		if input.RollbackSourceVersion == nil {
153			input.RollbackSourceVersion = input.RollbackFromVersion
154		}
155		if len(input.Items) == 0 {
156			input.Items = input.ConfigItems
157		}
158	
159		result, err := tx.Exec(
160			`INSERT INTO config_versions(namespace, environment, version, gray_label, rollback_source_version)
161			 VALUES (?, ?, ?, ?, ?)`,
162			input.Namespace, input.Environment, input.Version, input.GrayLabel, input.RollbackSourceVersion,
163		)
164		if err != nil {
165			return fmt.Errorf("insert version: %w", err)
166		}
167		versionID, err := result.LastInsertId()
168		if err != nil {
169			return fmt.Errorf("version id: %w", err)
170		}
171	
172		names := make([]string, 0, len(input.Items))
173		for name := range input.Items {
174			names = append(names, name)
175		}
176		sort.Strings(names)
177		for _, name := range names {
178			value, err := compactJSON(input.Items[name])
179			if err != nil {
180				return fmt.Errorf("normalize value for %q: %w", name, err)
181			}
182			if _, err := tx.Exec(
183				`INSERT INTO config_items(version_id, name, value) VALUES (?, ?, ?)`,
184				versionID, name, string(value),
185			); err != nil {
186				return fmt.Errorf("insert item %q: %w", name, err)
187			}
188		}
189	
190		if err := tx.Commit(); err != nil {
191			return fmt.Errorf("commit publish: %w", err)
192		}
193		return nil
194	}
