168	func handleVersionDiff(c *gin.Context, st *store.Store) {
169		namespace := firstValue(c, "namespace", "ns")
170		environment := firstValue(c, "environment", "env")
171		if namespace == "" || environment == "" {
172			respondDiffError(c, http.StatusBadRequest, "MISSING_SCOPE", "namespace and environment are required")
173			return
174		}
175	
176		baseText := firstValue(c, "baseVersion", "baselineVersion", "fromVersion", "base")
177		targetText := firstValue(c, "targetVersion", "baselineTargetVersion", "compareVersion", "toVersion", "target")
178		baseNumber, baseOK := parsePositiveVersion(baseText)
179		targetNumber, targetOK := parsePositiveVersion(targetText)
180		if !baseOK || !targetOK {
181			respondDiffError(c, http.StatusBadRequest, "INVALID_VERSION", "version must be a positive integer")
182			return
183		}
184		if targetNumber < baseNumber {
185			respondDiffError(c, http.StatusConflict, "VERSION_ORDER_CONFLICT", "target version must not be older than base version")
186			return
187		}
188	
189		baseVersion, err := st.GetVersion(namespace, environment, baseNumber)
190		if err != nil {
191			respondVersionLookupError(c, err)
192			return
193		}
194		targetVersion, err := st.GetVersion(namespace, environment, targetNumber)
195		if err != nil {
196			respondVersionLookupError(c, err)
197			return
198		}
199	
200		currentNumber, hasCurrent, err := st.ActiveVersion(namespace, environment)
201		if err != nil {
202			respondStorageError(c)
203			return
204		}
205		var currentVersion *store.Version
206		if hasCurrent {
207			currentVersion, err = st.GetVersion(namespace, environment, currentNumber)
208			if err != nil && !errors.Is(err, store.ErrVersionNotFound) && !errors.Is(err, store.ErrVersionScopeMismatch) {
209				respondStorageError(c)
210				return
211			}
212			if errors.Is(err, store.ErrVersionNotFound) || errors.Is(err, store.ErrVersionScopeMismatch) {
213				currentVersion = nil
214			}
215		}
216	
217		diffs := buildConfigChanges(baseVersion, targetVersion, currentVersion)
218		affectsCurrent := false
219		for _, diff := range diffs {
220			if diff.AffectsCurrent {
221				affectsCurrent = true
222				break
223			}
224		}
225		var current *int64
226		if hasCurrent {
227			current = &currentNumber
228		}
229		c.JSON(http.StatusOK, diffResponse{
230			Namespace:      namespace,
231			Environment:    environment,
232			BaseVersion:    toVersionInfo(baseVersion),
233			TargetVersion:  toVersionInfo(targetVersion),
234			CurrentVersion: current,
235			ChangedCount:   len(diffs),
236			Diffs:          diffs,
237			AffectsCurrent: affectsCurrent,
238		})
239	}
