    38	func looksLikeVersionDiffQuery(c *gin.Context) bool {
    39		path := c.Request.URL.Path
    40		if !containsAny(strings.ToLower(path), "diff", "compare", "history", "version") {
    41			return false
    42		}
    43		base := c.Query("baseVersion")
    44		if base == "" {
    45			base = c.Query("baselineVersion")
    46		}
    47		if base == "" {
    48			base = c.Query("fromVersion")
    49		}
    50		target := c.Query("targetVersion")
    51		if target == "" {
    52			target = c.Query("toVersion")
    53		}
    54		return base != "" && target != ""
    55	}
